-- PostgreSQL 16+. Chạy trên database trống. Không xóa dữ liệu cũ.
-- Sinh từ RentalDb; không trộn với bộ SQL V2 cũ.
BEGIN;
CREATE TABLE attachments (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "IsPublic" boolean NOT NULL,
    "EntityType" character varying(20) NOT NULL,
    "EntityId" integer NOT NULL,
    "OriginalName" character varying(250) NOT NULL,
    "StoredName" character varying(64) NOT NULL,
    "ContentType" character varying(100) NOT NULL,
    "Size" bigint NOT NULL,
    "CreatedAt" timestamp with time zone NOT NULL,
    "CreatedBy" character varying(2000) NOT NULL,
    "IsArchived" boolean NOT NULL,
    CONSTRAINT "PK_attachments" PRIMARY KEY ("Id"),
    CONSTRAINT ck_attachment_values CHECK ("Size" > 0 AND "EntityType" IN ('room','tenant','contract','incident','payment'))
);


CREATE TABLE audit_entries (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "Action" character varying(2000) NOT NULL,
    "Detail" character varying(2000) NOT NULL,
    "CreatedAt" timestamp with time zone NOT NULL,
    "CreatedBy" character varying(2000) NOT NULL,
    "IsArchived" boolean NOT NULL,
    CONSTRAINT "PK_audit_entries" PRIMARY KEY ("Id")
);


CREATE TABLE branches (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "Name" character varying(100) NOT NULL,
    "Address" character varying(2000) NOT NULL,
    "CreatedAt" timestamp with time zone NOT NULL,
    "CreatedBy" character varying(2000) NOT NULL,
    "IsArchived" boolean NOT NULL,
    CONSTRAINT "PK_branches" PRIMARY KEY ("Id")
);


CREATE TABLE fees (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "BranchId" integer NOT NULL,
    "Name" character varying(100) NOT NULL,
    "Method" character varying(20) NOT NULL,
    "UnitPrice" bigint NOT NULL,
    "CreatedAt" timestamp with time zone NOT NULL,
    "CreatedBy" character varying(2000) NOT NULL,
    "IsArchived" boolean NOT NULL,
    CONSTRAINT "PK_fees" PRIMARY KEY ("Id"),
    CONSTRAINT ck_fee_values CHECK ("UnitPrice" >= 0 AND "Method" IN ('Electricity','Water','Fixed','PerPerson')),
    CONSTRAINT "FK_fees_branches_BranchId" FOREIGN KEY ("BranchId") REFERENCES branches ("Id") ON DELETE RESTRICT
);


CREATE TABLE rooms (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "BranchId" integer NOT NULL,
    "Name" character varying(50) NOT NULL,
    "Price" bigint NOT NULL,
    "Capacity" integer NOT NULL,
    "IsMaintenance" boolean NOT NULL,
    "Description" character varying(2000) NOT NULL,
    "CreatedAt" timestamp with time zone NOT NULL,
    "CreatedBy" character varying(2000) NOT NULL,
    "IsArchived" boolean NOT NULL,
    CONSTRAINT "PK_rooms" PRIMARY KEY ("Id"),
    CONSTRAINT ck_room_values CHECK ("Price" >= 0 AND "Capacity" BETWEEN 1 AND 50),
    CONSTRAINT "FK_rooms_branches_BranchId" FOREIGN KEY ("BranchId") REFERENCES branches ("Id") ON DELETE RESTRICT
);


CREATE TABLE tenants (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "BranchId" integer NOT NULL,
    "FullName" character varying(100) NOT NULL,
    "Phone" character varying(20) NOT NULL,
    "IdentityNumber" character varying(30) NOT NULL,
    "Address" character varying(2000) NOT NULL,
    "CreatedAt" timestamp with time zone NOT NULL,
    "CreatedBy" character varying(2000) NOT NULL,
    "IsArchived" boolean NOT NULL,
    CONSTRAINT "PK_tenants" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_tenants_branches_BranchId" FOREIGN KEY ("BranchId") REFERENCES branches ("Id") ON DELETE RESTRICT
);


CREATE TABLE contracts (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "RoomId" integer NOT NULL,
    "StartDate" date NOT NULL,
    "EndDate" date NOT NULL,
    "ClosedDate" date,
    "Rent" bigint NOT NULL,
    "Deposit" bigint NOT NULL,
    "Status" character varying(20) NOT NULL,
    "Note" character varying(2000) NOT NULL,
    "CreatedAt" timestamp with time zone NOT NULL,
    "CreatedBy" character varying(2000) NOT NULL,
    "IsArchived" boolean NOT NULL,
    CONSTRAINT "PK_contracts" PRIMARY KEY ("Id"),
    CONSTRAINT ck_contract_status CHECK ("Status" IN ('Active','Closed')),
    CONSTRAINT ck_contract_values CHECK ("Rent" >= 0 AND "Deposit" >= 0 AND "EndDate" >= "StartDate"),
    CONSTRAINT "FK_contracts_rooms_RoomId" FOREIGN KEY ("RoomId") REFERENCES rooms ("Id") ON DELETE RESTRICT
);


CREATE TABLE incidents (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "RoomId" integer NOT NULL,
    "ReportedByTenantId" integer,
    "Description" character varying(2000) NOT NULL,
    "Status" character varying(20) NOT NULL,
    "Resolution" character varying(2000) NOT NULL,
    "Cost" bigint NOT NULL,
    "CreatedAt" timestamp with time zone NOT NULL,
    "CreatedBy" character varying(2000) NOT NULL,
    "IsArchived" boolean NOT NULL,
    CONSTRAINT "PK_incidents" PRIMARY KEY ("Id"),
    CONSTRAINT ck_incident_values CHECK ("Cost" >= 0 AND "Status" IN ('Open','InProgress','Resolved')),
    CONSTRAINT "FK_incidents_rooms_RoomId" FOREIGN KEY ("RoomId") REFERENCES rooms ("Id") ON DELETE RESTRICT,
    CONSTRAINT "FK_incidents_tenants_ReportedByTenantId" FOREIGN KEY ("ReportedByTenantId") REFERENCES tenants ("Id") ON DELETE RESTRICT
);


CREATE TABLE users (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "Username" character varying(50) NOT NULL,
    "FullName" character varying(100) NOT NULL,
    "PasswordHash" character varying(2000) NOT NULL,
    "Role" character varying(20) NOT NULL,
    "IsActive" boolean NOT NULL,
    "TenantId" integer,
    "CreatedAt" timestamp with time zone NOT NULL,
    "CreatedBy" character varying(2000) NOT NULL,
    "IsArchived" boolean NOT NULL,
    CONSTRAINT "PK_users" PRIMARY KEY ("Id"),
    CONSTRAINT ck_user_role CHECK ("Role" IN ('Owner','Manager','Tenant')),
    CONSTRAINT ck_user_tenant CHECK (("Role" = 'Tenant' AND "TenantId" IS NOT NULL) OR ("Role" <> 'Tenant' AND "TenantId" IS NULL)),
    CONSTRAINT "FK_users_tenants_TenantId" FOREIGN KEY ("TenantId") REFERENCES tenants ("Id") ON DELETE RESTRICT
);


CREATE TABLE contract_tenants (
    "ContractId" integer NOT NULL,
    "TenantId" integer NOT NULL,
    "IsRepresentative" boolean NOT NULL,
    CONSTRAINT "PK_contract_tenants" PRIMARY KEY ("ContractId", "TenantId"),
    CONSTRAINT "FK_contract_tenants_contracts_ContractId" FOREIGN KEY ("ContractId") REFERENCES contracts ("Id") ON DELETE RESTRICT,
    CONSTRAINT "FK_contract_tenants_tenants_TenantId" FOREIGN KEY ("TenantId") REFERENCES tenants ("Id") ON DELETE RESTRICT
);


CREATE TABLE deposit_entries (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "ContractId" integer NOT NULL,
    "Type" character varying(20) NOT NULL,
    "Amount" bigint NOT NULL,
    "Note" character varying(2000) NOT NULL,
    "CreatedAt" timestamp with time zone NOT NULL,
    "CreatedBy" character varying(2000) NOT NULL,
    "IsArchived" boolean NOT NULL,
    CONSTRAINT "PK_deposit_entries" PRIMARY KEY ("Id"),
    CONSTRAINT ck_deposit_values CHECK ("Amount" > 0 AND "Type" IN ('Received','Applied','Deducted','Refunded')),
    CONSTRAINT "FK_deposit_entries_contracts_ContractId" FOREIGN KEY ("ContractId") REFERENCES contracts ("Id") ON DELETE RESTRICT
);


CREATE TABLE invoices (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "ContractId" integer NOT NULL,
    "Year" integer NOT NULL,
    "Month" integer NOT NULL,
    "DueDate" date NOT NULL,
    "Total" bigint NOT NULL,
    "Status" character varying(20) NOT NULL,
    "CancellationReason" character varying(2000) NOT NULL,
    "CreatedAt" timestamp with time zone NOT NULL,
    "CreatedBy" character varying(2000) NOT NULL,
    "IsArchived" boolean NOT NULL,
    CONSTRAINT "PK_invoices" PRIMARY KEY ("Id"),
    CONSTRAINT ck_invoice_status CHECK ("Status" IN ('Issued','Cancelled')),
    CONSTRAINT ck_invoice_values CHECK ("Total" >= 0 AND "Month" BETWEEN 1 AND 12 AND "Year" BETWEEN 2000 AND 2100),
    CONSTRAINT "FK_invoices_contracts_ContractId" FOREIGN KEY ("ContractId") REFERENCES contracts ("Id") ON DELETE RESTRICT
);


CREATE TABLE readings (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "ContractId" integer NOT NULL,
    "Year" integer NOT NULL,
    "Month" integer NOT NULL,
    "ElectricityOld" numeric(18,3) NOT NULL,
    "ElectricityNew" numeric(18,3) NOT NULL,
    "WaterOld" numeric(18,3) NOT NULL,
    "WaterNew" numeric(18,3) NOT NULL,
    "CreatedAt" timestamp with time zone NOT NULL,
    "CreatedBy" character varying(2000) NOT NULL,
    "IsArchived" boolean NOT NULL,
    CONSTRAINT "PK_readings" PRIMARY KEY ("Id"),
    CONSTRAINT ck_reading_period CHECK ("Month" BETWEEN 1 AND 12 AND "Year" BETWEEN 2000 AND 2100),
    CONSTRAINT ck_reading_values CHECK ("ElectricityOld" >= 0 AND "ElectricityNew" >= "ElectricityOld" AND "WaterOld" >= 0 AND "WaterNew" >= "WaterOld"),
    CONSTRAINT "FK_readings_contracts_ContractId" FOREIGN KEY ("ContractId") REFERENCES contracts ("Id") ON DELETE RESTRICT
);


CREATE TABLE user_branches (
    "UserId" integer NOT NULL,
    "BranchId" integer NOT NULL,
    CONSTRAINT "PK_user_branches" PRIMARY KEY ("UserId", "BranchId"),
    CONSTRAINT "FK_user_branches_branches_BranchId" FOREIGN KEY ("BranchId") REFERENCES branches ("Id") ON DELETE RESTRICT,
    CONSTRAINT "FK_user_branches_users_UserId" FOREIGN KEY ("UserId") REFERENCES users ("Id") ON DELETE RESTRICT
);


CREATE TABLE invoice_items (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "InvoiceId" integer NOT NULL,
    "Description" character varying(2000) NOT NULL,
    "Quantity" numeric(18,3) NOT NULL,
    "UnitPrice" bigint NOT NULL,
    "Amount" bigint NOT NULL,
    CONSTRAINT "PK_invoice_items" PRIMARY KEY ("Id"),
    CONSTRAINT ck_item_values CHECK ("Quantity" >= 0 AND "UnitPrice" >= 0 AND "Amount" >= 0),
    CONSTRAINT "FK_invoice_items_invoices_InvoiceId" FOREIGN KEY ("InvoiceId") REFERENCES invoices ("Id") ON DELETE RESTRICT
);


CREATE TABLE payments (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "InvoiceId" integer NOT NULL,
    "Amount" bigint NOT NULL,
    "Method" character varying(20) NOT NULL,
    "PaidDate" date NOT NULL,
    "Note" character varying(2000) NOT NULL,
    "CreatedAt" timestamp with time zone NOT NULL,
    "CreatedBy" character varying(2000) NOT NULL,
    "IsArchived" boolean NOT NULL,
    CONSTRAINT "PK_payments" PRIMARY KEY ("Id"),
    CONSTRAINT ck_payment_values CHECK ("Amount" > 0 AND "Method" IN ('Cash','Transfer','Deposit')),
    CONSTRAINT "FK_payments_invoices_InvoiceId" FOREIGN KEY ("InvoiceId") REFERENCES invoices ("Id") ON DELETE RESTRICT
);


CREATE INDEX "IX_attachments_EntityType_EntityId" ON attachments ("EntityType", "EntityId");


CREATE UNIQUE INDEX "IX_contract_tenants_ContractId" ON contract_tenants ("ContractId") WHERE "IsRepresentative" = true;


CREATE INDEX "IX_contract_tenants_TenantId" ON contract_tenants ("TenantId");


CREATE UNIQUE INDEX "IX_contracts_RoomId" ON contracts ("RoomId") WHERE "Status" = 'Active';


CREATE INDEX "IX_deposit_entries_ContractId" ON deposit_entries ("ContractId");


CREATE UNIQUE INDEX "IX_fees_BranchId_Method" ON fees ("BranchId", "Method") WHERE "Method" IN ('Electricity','Water') AND "IsArchived" = false;


CREATE UNIQUE INDEX "IX_fees_BranchId_Name" ON fees ("BranchId", "Name");


CREATE INDEX "IX_incidents_ReportedByTenantId" ON incidents ("ReportedByTenantId");


CREATE INDEX "IX_incidents_RoomId" ON incidents ("RoomId");


CREATE INDEX "IX_invoice_items_InvoiceId" ON invoice_items ("InvoiceId");


CREATE UNIQUE INDEX "IX_invoices_ContractId_Year_Month" ON invoices ("ContractId", "Year", "Month") WHERE "Status" = 'Issued';


CREATE INDEX "IX_payments_InvoiceId" ON payments ("InvoiceId");


CREATE UNIQUE INDEX "IX_readings_ContractId_Year_Month" ON readings ("ContractId", "Year", "Month");


CREATE UNIQUE INDEX "IX_rooms_BranchId_Name" ON rooms ("BranchId", "Name");


CREATE INDEX "IX_tenants_BranchId" ON tenants ("BranchId");


CREATE INDEX "IX_user_branches_BranchId" ON user_branches ("BranchId");


CREATE UNIQUE INDEX "IX_users_TenantId" ON users ("TenantId");


CREATE UNIQUE INDEX "IX_users_Username" ON users ("Username");



COMMIT;
